"use client";
import * as React from "react";
import { Tooltip as BaseTooltip } from "@base-ui-components/react/tooltip";
import { cn } from "@/lib/utils";

// shadcn-style Tooltip on the Base UI primitive. Colors are theme tokens only.
export const TooltipProvider = BaseTooltip.Provider;
export const Tooltip = BaseTooltip.Root;
export const TooltipTrigger = BaseTooltip.Trigger;

// `container` lets a caller mount the popup inside a themed subtree (portals default
// to <body>, which sits outside a container that is previewing a theme).
export function TooltipContent({
  className,
  children,
  container,
  ...props
}: React.ComponentProps<typeof BaseTooltip.Popup> & {
  container?: React.ComponentProps<typeof BaseTooltip.Portal>["container"];
}) {
  return (
    <BaseTooltip.Portal container={container}>
      <BaseTooltip.Positioner sideOffset={6}>
        <BaseTooltip.Popup
          className={cn(
            "rounded-md bg-foreground px-2 py-1 text-xs font-medium text-background shadow-md",
            className
          )}
          {...props}
        >
          {children}
        </BaseTooltip.Popup>
      </BaseTooltip.Positioner>
    </BaseTooltip.Portal>
  );
}
